mapper.select:
SELECT spec_id, material_id, origin, package_weight, package_unit_label, created_at, updated_at
FROM material_package_spec
WHERE spec_id = #{specId}

mapper.update:
UPDATE material_package_spec
SET origin             = #{origin},
    package_weight     = #{packageWeight},
    package_unit_label = #{packageUnitLabel}
WHERE spec_id = #{specId}
